INSERT INTO `quizzes` VALUES (1,4,'가벼운_상식퀴즈','[{\"options\": [\"부산\", \"서울\", \"대전\", \"광주\"], \"question\": \"대한민국의 수도는 어디인가요?\", \"answerIndex\": 1}, {\"options\": [\"5일\", \"6일\", \"7일\", \"8일\"], \"question\": \"1주일은 며칠인가요?\", \"answerIndex\": 2}, {\"options\": [\"빨강\", \"노랑\", \"파랑\", \"검정\"], \"question\": \"바다의 색깔은 보통 무엇으로 표현하나요?\", \"answerIndex\": 2}, {\"options\": [\"O\", \"X\"], \"question\": \"사과는 나무에서 자라나요?\", \"answerIndex\": 0}, {\"options\": [\"12\", \"18\", \"24\", \"30\"], \"question\": \"하루는 몇 시간인가요?\", \"answerIndex\": 2}]'),(2,5,'OX_헷갈리는문제모음','[{\"options\": [\"O\", \"X\"], \"question\": \"고래는 물고기이다.\", \"answerIndex\": 1}, {\"options\": [\"O\", \"X\"], \"question\": \"번개는 천둥보다 먼저 친다.\", \"answerIndex\": 0}, {\"options\": [\"O\", \"X\"], \"question\": \"달은 스스로 빛을 낸다.\", \"answerIndex\": 1}, {\"options\": [\"O\", \"X\"], \"question\": \"모든 새는 날 수 있다.\", \"answerIndex\": 1}, {\"options\": [\"O\", \"X\"], \"question\": \"지구는 둥글다.\", \"answerIndex\": 0}]'),(3,6,'운빨테스트_퀴즈','[{\"options\": [\"앞\", \"뒤\"], \"question\": \"동전의 앞면은?\", \"answerIndex\": 0}, {\"options\": [\"5\", \"6\", \"7\", \"8\"], \"question\": \"주사위 최대 숫자는?\", \"answerIndex\": 1}, {\"options\": [\"좋음\", \"보통\", \"나쁨\", \"모르겠음\"], \"question\": \"오늘 기분은?\", \"answerIndex\": 3}, {\"options\": [\"1번\", \"2번\", \"3번\", \"랜덤\"], \"question\": \"이 문제 정답은?\", \"answerIndex\": 3}, {\"options\": [\"0%\", \"25%\", \"50%\", \"100%\"], \"question\": \"찍어도 맞을 확률은?\", \"answerIndex\": 2}]'),(4,7,'한문제는_꼭틀림','[{\"options\": [\"1\", \"2\", \"3\", \"4\"], \"question\": \"손은 몇 개일까요?\", \"answerIndex\": 1}, {\"options\": [\"1\", \"2\", \"3\", \"4\"], \"question\": \"눈은 몇 개인가요?\", \"answerIndex\": 1}, {\"options\": [\"1\", \"2\", \"3\", \"4\"], \"question\": \"발은 몇 개인가요?\", \"answerIndex\": 1}, {\"options\": [\"1\", \"2\", \"3\", \"4\"], \"question\": \"귀는 몇 개인가요?\", \"answerIndex\": 1}, {\"options\": [\"1\", \"2\", \"3\", \"4\"], \"question\": \"코는 몇 개인가요?\", \"answerIndex\": 0}]'),(5,8,'가족용_쉬운퀴즈','[{\"o